  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B008",
      "proposed_laureates": [
        "Christopher Jarzynski",
        "Gavin E. Crooks",
        "Denis J. Evans"
      ],
      "assessment": {
        "nobel_worthiness": "The fluctuation theorems give precise, broadly applicable relations for nonequilibrium systems and connect microscopic dynamics to thermodynamics. Their conceptual reach and influence make this a strong prize case.",
        "attribution": "Evans's early fluctuation relation, Jarzynski's equality, and Crooks's relation are distinct central contributions. Three-person credit is defensible, though the wider development of nonequilibrium statistical mechanics complicates boundaries.",
        "maturity": "The results have been tested across varied physical systems and underpin substantial theoretical and experimental work; their significance is well established.",
        "uncertainties": [
          "The relationship among the different theorems and their precursors makes a sharp division of credit difficult."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B045",
      "proposed_laureates": [
        "Alexei Kitaev",
        "Peter W. Shor",
        "Andrew M. Steane"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction established how quantum information can be protected despite noise, turning a major obstacle into a principled field of research with deep consequences for quantum physics and computation.",
        "attribution": "Kitaev, Shor, and Steane made foundational contributions to topological, general, and practical quantum error-correcting codes. Their complementary roles support shared recognition.",
        "maturity": "Error correction has been demonstrated in increasingly capable quantum platforms, and its theoretical foundations are secure. Full fault-tolerant computing remains under development.",
        "uncertainties": [
          "The boundary between foundational theory and later experimental realization leaves room for disagreement about the appropriate scope of a prize."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Eli Yablonovitch",
        "Sajeev John",
        "John D. Joannopoulos"
      ],
      "assessment": {
        "nobel_worthiness": "Photonic crystals made control of light through periodic structure a powerful and broadly useful idea, with lasting impact across photonics and the physics of waves in structured media.",
        "attribution": "Yablonovitch and John independently articulated the key photonic band-gap concept; Joannopoulos helped develop its theoretical framework and establish the field. Credit among these contributions should be carefully delimited.",
        "maturity": "The concept has been experimentally realized and developed for decades, with a substantial body of applications and fundamental work.",
        "uncertainties": [
          "The relative weight of the original proposals, theoretical development, and subsequent device applications is not straightforward."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B035",
      "proposed_laureates": [
        "Juan Maldacena",
        "Edward Witten"
      ],
      "assessment": {
        "nobel_worthiness": "Gauge/gravity duality is an unusually deep connection between quantum field theory and gravity that has reshaped theoretical physics and generated useful tools across several areas.",
        "attribution": "Maldacena's proposal is the landmark discovery; Witten's work helped establish and extend the correspondence. Polyakov's earlier ideas are relevant to the historical foundations, so the credit boundary deserves care.",
        "maturity": "The duality is mathematically influential and extensively studied, but its relation to the observed universe and direct experimental tests remains unresolved.",
        "uncertainties": [
          "The absence of direct empirical confirmation limits assessment of its physical status.",
          "The foundational intellectual lineage extends beyond the proposed laureates."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B038",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks have transformed precision measurement and opened tests of fundamental physics through unprecedented frequency stability and accuracy.",
        "attribution": "Katori's lattice-clock proposal and development and Ye's major experimental advances form a strong, complementary case for shared credit.",
        "maturity": "The method is established, repeatedly realized, and advancing rapidly, with clear scientific use beyond metrology itself.",
        "uncertainties": [
          "The technology continues to improve, so the eventual scope of its fundamental impact is still unfolding."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B021",
      "proposed_laureates": [
        "Antoine Georges",
        "Dieter Vollhardt",
        "Gabriel Kotliar"
      ],
      "assessment": {
        "nobel_worthiness": "Dynamical mean-field theory supplied a tractable framework for strongly correlated electrons and has become a central tool for understanding materials where simpler approximations fail.",
        "attribution": "The method emerged through closely related contributions by Georges, Vollhardt, and Kotliar. Shared credit is appropriate, though the precise division among its formulation, implementation, and applications is complex.",
        "maturity": "The framework has been developed, benchmarked, and applied over decades, with clear influence on condensed-matter theory and materials research.",
        "uncertainties": [
          "Its status as a foundational discovery versus a highly successful theoretical method may divide views on prize scale."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B023",
      "proposed_laureates": [
        "Immanuel Bloch",
        "Markus Greiner",
        "Peter Zoller"
      ],
      "assessment": {
        "nobel_worthiness": "Ultracold atoms in optical lattices made controlled quantum simulation of many-body systems possible, linking precision experiments to fundamental questions in condensed matter and statistical physics.",
        "attribution": "Bloch and Greiner established key experimental capabilities, while Zoller helped develop the theoretical vision for quantum simulation with trapped atoms. The contributions are substantial but span a larger community.",
        "maturity": "The platform has produced influential results over many years and continues to develop; its ability to resolve difficult questions about strongly correlated matter is still growing.",
        "uncertainties": [
          "The field's broad experimental and theoretical contributions make a three-person boundary difficult."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B005",
      "proposed_laureates": [
        "Claudio Castelnovo",
        "Roderich Moessner",
        "Shivaji L. Sondhi"
      ],
      "assessment": {
        "nobel_worthiness": "The prediction of emergent magnetic monopole-like excitations in spin ice is a striking example of collective behavior producing new effective particles, and it gave frustrated magnetism a memorable conceptual result.",
        "attribution": "Castelnovo, Moessner, and Sondhi jointly formulated the influential monopole picture. The theoretical result and its experimental signatures should be considered together.",
        "maturity": "Spin-ice monopole behavior has been investigated in real materials for many years, though these excitations are emergent quasiparticles rather than isolated fundamental monopoles.",
        "uncertainties": [
          "The breadth of impact beyond frustrated magnetism is more limited than for some competing discoveries.",
          "The analogy to fundamental magnetic monopoles can overstate what the experiments establish."
        ]
      }
    }
  ]
}
